templateScript:
// ---- Habit Tracker - Templates (A4 portrait, 595 x 842 pt) ----
const WEEK_STARTS_MONDAY = true;   // set to false for a Sun-Sat calendar

const W = A4_WIDTH;                // 595
const H = A4_HEIGHT;               // 842
const M = 48;                      // left/right margin
const CW = W - 2 * M;              // content width: 499

const SERIF = "Playfair Display";
const SANS = "Inter";
const INK = "#1f1f1f";
const MUTED = "#767676";
const RULE = "#cfcfcf";

// Helpers that fill in every required base property
const base = (id, type, x, y, w, h, extra = {}) => ({
  id, type, x, y, w, h,
  rotation: 0, fill: "none", stroke: "none", strokeWidth: 0, opacity: 1,
  ...extra,
});

const text = (id, x, y, w, h, str, opts = {}) => base(id, "text", x, y, w, h, {
  text: str,
  fontSize: 12, fontFamily: SANS, textColor: INK,
  fontWeight: "normal", fontStyle: "normal", textDecoration: "none",
  align: "left", verticalAlign: "middle", autoWidth: false,
  ...opts,
});

const label = (id, x, y, w, h, str, opts = {}) =>
  text(id, x, y, w, h, str, { fontSize: 11, fontWeight: "bold", textColor: MUTED, ...opts });

const rule = (id, x, y, w) => base(id, "rect", x, y, w, 1, { fill: RULE });

const tickBox = (id, x, y, size) => base(id, "rect", x, y, size, size, {
  stroke: INK, strokeWidth: 1.4,
  borderRadius: 4, borderStyle: "solid", fillType: "solid",
});

// ================= Month page =================
const GAP = 5;
const CELL_W = (CW - 6 * GAP) / 7;   // 67 = width of ONE cell (7 cells + 6 gaps = 499)
const CELL_H = 64;                   // up to 6 rows -> 6*64 + 5*5 = 409 pt tall
const GRID_Y = 150;

const DAY_NAMES = WEEK_STARTS_MONDAY
  ? ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"]
  : ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

const monthElements = [
  label("m_kicker", M, 44, CW, 16, "HABIT TRACKER"),
  text("m_title", M, 62, CW, 50, "{{monthLabel}}",
    { fontFamily: SERIF, fontSize: 38, fontWeight: "bold" }),

  ...DAY_NAMES.map((d, c) =>
    label(`m_wd_${c}`, M + c * (CELL_W + GAP), 126, CELL_W, 18, d,
      { fontSize: 10, align: "center" })),

  // Calendar: one cell per day; every cell links to that day's page
  base("m_calendar", "grid", M, GRID_Y, CELL_W, CELL_H, {
    fontSize: 18, fontFamily: SANS, textColor: INK, fontWeight: "normal",
    align: "center", verticalAlign: "middle",
    gridConfig: {
      cols: 7, gapX: GAP, gapY: GAP,
      sourceType: "current", sourceId: "",
      displayField: "dayNum",
      offsetMode: "dynamic",
      offsetField: WEEK_STARTS_MONDAY ? "offsetMon" : "offsetSun",
      offsetAdjustment: 0,
      dataSliceStart: 0, dataSliceCount: 31,
      gridBorderMode: "all", gridBorderColor: "#b5b5b5", gridBorderWidth: 1,
      gridBorderStyle: "solid", gridBorderRadius: 6, showEmptyCellBorders: false,
    },
  }),

  label("m_habits", M, 592, CW, 16, "MY HABITS"),
];

// Habit list: 1-5 in the left column, 6-10 in the right
const COL_GAP = 24;
const COL_W = (CW - COL_GAP) / 2;
for (let i = 0; i < 10; i++) {
  const n = i + 1;
  const x = M + Math.floor(i / 5) * (COL_W + COL_GAP);
  const y = 616 + (i % 5) * 36;
  monthElements.push(
    label(`m_hn_${n}`, x, y, 16, 24, String(n), { align: "right" }),
    text(`m_h_${n}`, x + 24, y, COL_W - 24, 24, `{{habit${n}}}`),
    rule(`m_hl_${n}`, x + 24, y + 25, COL_W - 24),
  );
}

// ================= Day page =================
const ROW_Y = 166;   // top of the first habit row
const ROW_H = 64;    // 10 rows -> ends at 806
const BOX = 24;      // tick box size

const dayElements = [
  // Navigation bar: previous day | month | next day
  label("d_prev", M, 30, 150, 28, "{{prevLabel}}",
    { linkTarget: "sibling", linkValue: "-1" }),
  label("d_month", W / 2 - 90, 30, 180, 28, "{{monthLabel}}",
    { align: "center", linkTarget: "parent" }),
  label("d_next", W - M - 150, 30, 150, 28, "{{nextLabel}}",
    { align: "right", linkTarget: "sibling", linkValue: "1" }),
  rule("d_nav_rule", M, 64, CW),

  text("d_weekday", M, 84, CW, 46, "{{weekday}}",
    { fontFamily: SERIF, fontSize: 34, fontWeight: "bold" }),
  text("d_date", M, 130, CW, 20, "{{dateLabel}}",
    { fontSize: 14, textColor: MUTED }),
];

// Ten habit rows: number, tick box, habit name on a writing line
for (let i = 0; i < 10; i++) {
  const n = i + 1;
  const y = ROW_Y + i * ROW_H + (ROW_H - BOX) / 2;
  dayElements.push(
    label(`d_hn_${n}`, M, y, 16, BOX, String(n), { align: "right" }),
    tickBox(`d_box_${n}`, M + 22, y, BOX),
    text(`d_h_${n}`, M + 60, y, CW - 60, BOX, `{{habit${n}}}`, { fontSize: 15 }),
    rule(`d_hl_${n}`, M + 60, y + BOX, CW - 60),
  );
}

const templates = {
  tpl_month: { id: "tpl_month", name: "Month", width: W, height: H, elements: monthElements },
  tpl_day:   { id: "tpl_day",   name: "Day",   width: W, height: H, elements: dayElements },
};
return templates;

hierarchyScript:
// ---- Habit Tracker - Hierarchy ----
const YEAR = 2026;
const MONTH = 11;   // 1 = January ... 12 = December

// Your ten habits, printed on the month page and on every day page.
// Leave an entry as "" to get a blank line you can write on instead,
// e.g. ["Drink 2 L of water", "Walk 8,000 steps", "Read 20 pages", ...]
const HABITS = ["", "", "", "", "", "", "", "", "", ""];

const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July",
  "August", "September", "October", "November", "December"];
const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const short = (wd) => WEEKDAYS[wd].slice(0, 3);

const monthName = MONTH_NAMES[MONTH - 1];
const monthLabel = `${monthName} ${YEAR}`;                   // "November 2026"
const daysInMonth = new Date(YEAR, MONTH, 0).getDate();      // 30
const firstWeekday = new Date(YEAR, MONTH - 1, 1).getDay();  // 0 = Sunday (1 Nov 2026 is a Sunday)

const habitData = {};
for (let i = 0; i < 10; i++) habitData[`habit${i + 1}`] = HABITS[i] || "";

const nodes = {};
const rootId = createId("month");

nodes[rootId] = {
  id: rootId,
  parentId: null,
  type: "tpl_month",
  title: monthLabel,
  data: { monthLabel, ...habitData },
  children: [],
};

for (let d = 1; d <= daysInMonth; d++) {
  const wd = new Date(YEAR, MONTH - 1, d).getDay();
  const id = createId("day");
  nodes[id] = {
    id,
    parentId: rootId,
    type: "tpl_day",
    title: `${short(wd)} ${d} ${monthName.slice(0, 3)}`,     // "Sun 1 Nov"
    data: {
      dayNum: String(d),                                      // shown in the calendar cell
      weekday: WEEKDAYS[wd],                                  // "Sunday"
      dateLabel: `${d} ${monthLabel}`,                        // "1 November 2026"
      monthLabel,
      prevLabel: d > 1 ? `‹ ${short((wd + 6) % 7)} ${d - 1}` : "",
      nextLabel: d < daysInMonth ? `${short((wd + 1) % 7)} ${d + 1} ›` : "",
      offsetSun: firstWeekday,              // calendar offset for Sunday-first weeks
      offsetMon: (firstWeekday + 6) % 7,    // calendar offset for Monday-first weeks
      ...habitData,
    },
    children: [],
  };
  nodes[rootId].children.push(id);
}

return { nodes, rootId };
